            <span class="journey__text">
              Getting started is easy. After download, follow these simple steps
              to improve your landlord experience.
            </span>
          </div>
          <div
            class="journey__step journey__step-desktop"
            :class="{ animate: show }"
            v-if="show"
          >
            <span class="journey__number">
              {{ steps[currentStep]?.number }}
            </span>
            <div
              class="journey__content"
              :style="{ backgroundColor: steps[currentStep]?.background }"
            >
              <div class="journey__details">
                <p class="journey__step-title">
                  {{ steps[currentStep]?.title }}
                </p>
                <p class="journey__desc">
                  {{ steps[currentStep]?.description }}
                </p>
              </div>
              <div
                class="journey-svg"
                v-html="steps[currentStep]?.journeySvg"
              ></div>
              <div
                class="journey__spacer"
                v-html="steps[currentStep]?.spacerSVG"
              ></div>

              <img
                class="journey__phone"
                :src="steps[currentStep]?.phone"
                alt="phone"
              />
            </div>
          </div>
          <div
            class="journey__step journey__step-mobile"
            v-for="(step, index) in steps"
            :key="index"
          >
            <span class="journey__number">
              {{ step.number }}
            </span>
            <div
              class="journey__content"
              :style="{ backgroundColor: step.background }"
            >
              <div class="journey__details">
                <p class="journey__step-title">
                  {{ step.title }}
                </p>
                <p class="journey__desc">
                  {{ step.description }}
                </p>
              </div>
              <div class="journey-svg" v-html="step.journeySvg"></div>
              <div class="journey__spacer" v-html="step.spacerSVG1"></div>

              <img class="journey__phone" :src="step.phone" alt="phone" />
            </div>
          </div>
        </div>
      </section>

      <section class="article-card">
        <div class="article-card__content">
          <div class="article-card-svg">
            <svg
