<style scoped>
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  scroll-behavior: smooth;
}

.main-container {
  width: 100%;
  height: auto;
  font-family: Aeonik;
  text-underline-position: from-font;
  text-decoration-skip-ink: none;
  transform: scale(1.1);
  animation: container 2s ease-out forwards;
}

@keyframes container {
  0% {
    transform: scale(1.5);
    opacity: 0;
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes section {
  from {
    opacity: 0;
    scale: 0.5;
    transform: translateX(-100px);
    /* clip-path: inset(100% 100% 0 0); */
  }

  to {
    opacity: 1;
    scale: 1;
    transform: translateX(0px);
    /* clip-path: inset(0 0 0 0); */
  }
}

section {
  width: 100%;
  height: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  padding: 1rem;
  margin-bottom: 6rem;
}
/* mission starts here */

.mission {
  width: 100%;
  max-height: 700px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 2rem 0rem;
  gap: 5rem;
}

.mission-statement {
  max-width: 1194px;
  height: auto;
  font-family: Aeonik;
  padding: 1rem;
  font-size: clamp(36px, 5vw, 61.04px);
  font-weight: 700;
  line-height: clamp(54px, 6vw, 73.25px);
  text-align: center;
  text-underline-position: from-font;
  text-decoration-skip-ink: none;
  transition: transform 0.3s ease, font-size 0.3s ease, line-height 0.3s ease;
  transform: scale(1);
  text-transform: capitalize;
}

.mission-statement:hover {
  transform: scale(1.05);
}

.download-links {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.download-links a {
  width: 250px;
  height: 72.22px;
  transition: background-color 0.3s ease, transform 0.3s ease;
    animation: section linear;
  animation-timeline: view();
  animation-range: entry 0% cover 40%;
}

.download-links a:hover {
  background-color: #f0f0f0;
  transform: scale(1.05);
}

/* mission end here */
.landlord {
  width: 100%;
  height: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12rem;
  color: white;
  animation: section linear;
  animation-timeline: view();
  animation-range: entry 0% cover 40%;
}

.landlord-info {
  width: 100%;
  max-width: 1240px;
  height: auto;
  border-radius: 30px;
  display: flex;
  justify-content: space-around;
  align-items: center;
  position: relative;
  padding: 1rem;
  background: #0b1f6b;
  flex-wrap: wrap;
}

.landlord-info:hover {
  background: #091c4f;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
  transition: background 0.4s ease, box-shadow 0.4s ease;
}

.landlord-section-title {
  font-size: clamp(22px, 4vw, 61.04px);
